CREATE OR REPLACE FUNCTION "public"."admin_list_recipient_registrations"() RETURNS SETOF "public"."recipient_registrations"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;
  RETURN QUERY SELECT * FROM public.recipient_registrations;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."calculate_distance"("lat1" numeric, "lon1" numeric, "lat2" numeric, "lon2" numeric) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r numeric := 6371;
  dlat numeric;
  dlon numeric;
  a numeric;
  c numeric;
BEGIN
  dlat := radians(lat2 - lat1);
  dlon := radians(lon2 - lon1);
  a := sin(dlat / 2) ^ 2 + cos(radians(lat1)) * cos(radians(lat2)) * sin(dlon / 2) ^ 2;
  c := 2 * atan2(sqrt(a), sqrt(1 - a));
  RETURN round(r * c);
END;
$$;




CREATE OR REPLACE FUNCTION "public"."calculate_user_impact_points"("_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _unit_count int;
  _unique_countries int;
  _reg_count int;
  _total int;
  _rank text;
  _ppu int;
  _ppc int;
  _ppr int;
BEGIN
  -- Dynamically fetch scoring config
  SELECT points_per_unit, points_per_country, points_per_registration
  INTO _ppu, _ppc, _ppr
  FROM public.gamification_config
  WHERE id = 1;

  -- Fallback defaults
  _ppu := COALESCE(_ppu, 10);
  _ppc := COALESCE(_ppc, 50);
  _ppr := COALESCE(_ppr, 100);

  SELECT
    COUNT(*)::int,
    COUNT(DISTINCT cd.country_id)::int
  INTO _unit_count, _unique_countries
  FROM public.inventory_units iu
  JOIN public.card_designs cd ON cd.id = iu.card_design_id
  WHERE iu.traveler_user_id = _user_id;

  SELECT COUNT(*)::int INTO _reg_count
  FROM public.recipient_registrations rr
  JOIN public.inventory_units iu ON iu.id = rr.inventory_unit_id
  WHERE iu.traveler_user_id = _user_id;

  _total := (_unit_count * _ppu) + (_unique_countries * _ppc) + (_reg_count * _ppr);

  -- Dynamically determine rank from gamification_tiers
  SELECT name INTO _rank
  FROM public.gamification_tiers
  WHERE min_points <= _total
  ORDER BY min_points DESC
  LIMIT 1;

  _rank := COALESCE(_rank, 'Zwiadowca');

  UPDATE public.profiles
  SET total_points = _total,
      current_rank = _rank
  WHERE user_id = _user_id;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."create_order"("_items" "jsonb", "_pickup_point_name" "text", "_pickup_point_address" "text", "_pickup_point_city" "text", "_shipping_cost" numeric, "_invoice_requested" boolean DEFAULT false, "_company_name" "text" DEFAULT NULL::"text", "_company_nip" "text" DEFAULT NULL::"text", "_company_address" "text" DEFAULT NULL::"text", "_payment_method" "text" DEFAULT 'online'::"text", "_shipping_method" "text" DEFAULT 'inpost'::"text", "_shipping_name" "text" DEFAULT NULL::"text", "_shipping_street" "text" DEFAULT NULL::"text", "_shipping_postal_code" "text" DEFAULT NULL::"text", "_shipping_city" "text" DEFAULT NULL::"text", "_shipping_phone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  _uid uuid := auth.uid(); _order_id uuid; _order_number text; _item jsonb; _design_id uuid; _qty int;
  _unit_price numeric(10,2); _price_grosze int; _total numeric(10,2) := 0; _nip_clean text;
  _expected_shipping numeric(10,2); _phone_clean text; _customer_email text := lower(trim(coalesce(auth.jwt() ->> 'email', '')));
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'unauthorized'; END IF;
  IF _customer_email = '' OR _customer_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN RAISE EXCEPTION 'customer_email_unavailable'; END IF;
  IF _items IS NULL OR jsonb_typeof(_items) <> 'array' OR jsonb_array_length(_items) = 0 THEN RAISE EXCEPTION 'empty_cart'; END IF;
  IF jsonb_array_length(_items) > 100 THEN RAISE EXCEPTION 'too_many_items'; END IF;
  IF _shipping_method IS NULL OR _shipping_method NOT IN ('inpost','courier') THEN RAISE EXCEPTION 'invalid_shipping_method'; END IF;
  IF _shipping_method = 'inpost' THEN
    IF coalesce(length(trim(_pickup_point_name)), 0) = 0 THEN RAISE EXCEPTION 'pickup_point_required'; END IF;
    _shipping_name := NULL; _shipping_street := NULL; _shipping_postal_code := NULL; _shipping_city := NULL; _shipping_phone := NULL;
  ELSE
    IF coalesce(length(trim(_shipping_name)), 0) = 0 THEN RAISE EXCEPTION 'shipping_name_required'; END IF;
    IF coalesce(length(trim(_shipping_street)), 0) = 0 THEN RAISE EXCEPTION 'shipping_street_required'; END IF;
    IF coalesce(length(trim(_shipping_postal_code)), 0) = 0 THEN RAISE EXCEPTION 'shipping_postal_code_required'; END IF;
    IF _shipping_postal_code !~ '^[0-9]{2}-[0-9]{3}$' THEN RAISE EXCEPTION 'shipping_postal_code_invalid'; END IF;
    IF coalesce(length(trim(_shipping_city)), 0) = 0 THEN RAISE EXCEPTION 'shipping_city_required'; END IF;
    _phone_clean := regexp_replace(coalesce(_shipping_phone, ''), '[^0-9+]', '', 'g');
    IF length(_phone_clean) < 9 OR length(_phone_clean) > 15 THEN RAISE EXCEPTION 'shipping_phone_invalid'; END IF;
    _shipping_phone := _phone_clean; _pickup_point_name := NULL; _pickup_point_address := NULL; _pickup_point_city := NULL;
  END IF;
  IF _payment_method IS NULL OR _payment_method NOT IN ('online','cod') THEN RAISE EXCEPTION 'invalid_payment_method'; END IF;
  _expected_shipping := CASE WHEN _payment_method = 'online' THEN 13.99 ELSE 16.99 END;
  IF _shipping_cost IS NULL OR _shipping_cost <> _expected_shipping THEN RAISE EXCEPTION 'invalid_shipping_cost'; END IF;
  IF _invoice_requested THEN
    IF coalesce(length(trim(_company_name)), 0) = 0 THEN RAISE EXCEPTION 'invoice_company_name_required'; END IF;
    IF coalesce(length(trim(_company_address)), 0) = 0 THEN RAISE EXCEPTION 'invoice_company_address_required'; END IF;
    _nip_clean := regexp_replace(coalesce(_company_nip, ''), '[^0-9]', '', 'g');
    IF NOT public.is_valid_nip(_nip_clean) THEN RAISE EXCEPTION 'invoice_nip_invalid'; END IF;
  ELSE _company_name := NULL; _company_nip := NULL; _company_address := NULL; _nip_clean := NULL; END IF;
  FOR _item IN SELECT * FROM jsonb_array_elements(_items) LOOP
    _design_id := (_item->>'card_design_id')::uuid; _qty := (_item->>'quantity')::int;
    IF _qty IS NULL OR _qty < 1 OR _qty > 1000 THEN RAISE EXCEPTION 'invalid_quantity'; END IF;
    SELECT price_grosze INTO _price_grosze FROM public.card_designs WHERE id = _design_id AND active = true AND price_grosze > 0;
    IF _price_grosze IS NULL THEN RAISE EXCEPTION 'invalid_design:%', _design_id; END IF;
    _unit_price := _price_grosze::numeric / 100.0; _total := _total + (_qty * _unit_price);
  END LOOP;
  _total := _total + _shipping_cost;
  INSERT INTO public.orders(user_id,total_amount,pickup_point_name,pickup_point_address,pickup_point_city,shipping_cost,invoice_requested,company_name,company_nip,company_address,payment_method,shipping_method,shipping_name,shipping_address,shipping_postal_code,shipping_city,shipping_country,shipping_phone,customer_email)
  VALUES (_uid,_total,_pickup_point_name,_pickup_point_address,_pickup_point_city,_shipping_cost,_invoice_requested,_company_name,_nip_clean,_company_address,_payment_method,_shipping_method,_shipping_name,_shipping_street,_shipping_postal_code,_shipping_city,CASE WHEN _shipping_method = 'courier' THEN 'Polska' ELSE NULL END,_shipping_phone,_customer_email)
  RETURNING id, order_number INTO _order_id, _order_number;
  FOR _item IN SELECT * FROM jsonb_array_elements(_items) LOOP
    _design_id := (_item->>'card_design_id')::uuid; _qty := (_item->>'quantity')::int;
    SELECT price_grosze INTO _price_grosze FROM public.card_designs WHERE id = _design_id;
    _unit_price := _price_grosze::numeric / 100.0;
    INSERT INTO public.order_items(order_id,card_design_id,quantity,unit_price,total_price) VALUES (_order_id,_design_id,_qty,_unit_price,_qty * _unit_price);
  END LOOP;
  RETURN jsonb_build_object('id',_order_id,'order_number',_order_number,'total_amount',_total,'payment_method',_payment_method,'shipping_method',_shipping_method);
END;
$_$;




CREATE OR REPLACE FUNCTION "public"."generate_claim_code"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  code TEXT;
  cnt INTEGER;
  chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  i INTEGER;
  part1 TEXT := '';
  part2 TEXT := '';
BEGIN
  LOOP
    part1 := '';
    part2 := '';
    FOR i IN 1..4 LOOP
      part1 := part1 || substr(chars, floor(random() * length(chars) + 1)::int, 1);
      part2 := part2 || substr(chars, floor(random() * length(chars) + 1)::int, 1);
    END LOOP;
    code := 'PDZ-' || part1 || '-' || part2;
    SELECT COUNT(*) INTO cnt FROM public.inventory_units WHERE public_claim_code = code;
    EXIT WHEN cnt = 0;
  END LOOP;
  RETURN code;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."generate_order_number"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  num TEXT;
  cnt INTEGER;
BEGIN
  LOOP
    num := 'ORD-' || to_char(now(), 'YYMMDD') || '-' || upper(substr(md5(random()::text), 1, 5));
    SELECT COUNT(*) INTO cnt FROM public.orders WHERE order_number = num;
    EXIT WHEN cnt = 0;
  END LOOP;
  RETURN num;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."generate_tracking_code"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    code TEXT;
    exists_count INTEGER;
BEGIN
    LOOP
        code := 'PL-' || upper(substr(md5(random()::text), 1, 8));
        SELECT COUNT(*) INTO exists_count FROM public.postcards WHERE tracking_code = code;
        EXIT WHEN exists_count = 0;
    END LOOP;
    RETURN code;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
