    VALUES (
      NEW.user_id,
      'AwansowaĹ‚eĹ›!',
      'Gratulacje, Twoja nowa ranga to ' || NEW.current_rank || '!',
      'rank_up'
    );
  END IF;
  RETURN NEW;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."on_inventory_unit_recalc_gamification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.traveler_user_id IS NOT NULL THEN
    PERFORM public.calculate_user_impact_points(NEW.traveler_user_id);
  END IF;
  RETURN NEW;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."on_registration_add_kilometers"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _traveler_id uuid;
  _dist integer;
BEGIN
  IF NEW.latitude IS NULL OR NEW.longitude IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT traveler_user_id INTO _traveler_id
  FROM public.inventory_units
  WHERE id = NEW.inventory_unit_id;

  IF _traveler_id IS NULL THEN
    RETURN NEW;
  END IF;

  _dist := public.calculate_distance(52.2297, 21.0122, NEW.latitude, NEW.longitude)::integer;

  UPDATE public.profiles
  SET total_kilometers = total_kilometers + _dist
  WHERE user_id = _traveler_id;

  RETURN NEW;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."on_registration_recalc_gamification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _traveler_id uuid;
BEGIN
  SELECT traveler_user_id INTO _traveler_id
  FROM public.inventory_units
  WHERE id = NEW.inventory_unit_id;

  IF _traveler_id IS NOT NULL THEN
    PERFORM public.calculate_user_impact_points(_traveler_id);
  END IF;

  RETURN NEW;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."on_shipment_shipped"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'shipped' AND (OLD.status IS DISTINCT FROM 'shipped') THEN
    -- Update shipped_at on shipment
    NEW.shipped_at := COALESCE(NEW.shipped_at, now());

    -- Update all inventory_units linked to this order
    UPDATE public.inventory_units
    SET fulfillment_status = 'shipped',
        shipped_at = now(),
        shipment_id = NEW.id::text
    WHERE order_id = NEW.order_id::text
      AND fulfillment_status IN ('reserved', 'qr_generated', 'qr_applied');
  END IF;

  IF NEW.status = 'delivered' AND (OLD.status IS DISTINCT FROM 'delivered') THEN
    NEW.delivered_at := COALESCE(NEW.delivered_at, now());
  END IF;

  RETURN NEW;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."prepare_pod_order"("_order_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _order public.orders%ROWTYPE;
  _item record;
  _job_id uuid;
  _batch_id uuid;
  _unit_id uuid;
  _claim_code text;
  _token text;
  _item_no integer := 0;
  _copy_no integer;
BEGIN
  SELECT * INTO _order
  FROM public.orders
  WHERE id = _order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found';
  END IF;

  IF _order.payment_status <> 'paid' THEN
    RAISE EXCEPTION 'order_not_paid';
  END IF;

  -- Idempotency protects against duplicate payment callbacks.
  SELECT id INTO _job_id
  FROM public.qr_print_jobs
  WHERE order_id = _order_id
  ORDER BY created_at DESC
  LIMIT 1;

  IF _job_id IS NOT NULL THEN
    RETURN _job_id;
  END IF;

  INSERT INTO public.qr_print_jobs (
    name, order_id, status, total_items, generated_items, created_by
  )
  VALUES (
    'POD â€” zamĂłwienie ' || _order.order_number,
    _order_id,
    'generating',
    0,
    0,
    _order.user_id
  )
  RETURNING id INTO _job_id;

  FOR _item IN
    SELECT id, card_design_id, quantity
    FROM public.order_items
    WHERE order_id = _order_id
    ORDER BY created_at, id
  LOOP
    -- A batch records the print run for traceability; it is not store stock.
    INSERT INTO public.stock_batches (name, description, card_design_id, quantity)
    VALUES (
      'POD ' || _order.order_number,
      'Sztuki utworzone automatycznie po opĹ‚aceniu zamĂłwienia.',
      _item.card_design_id,
      _item.quantity
    )
    RETURNING id INTO _batch_id;

    FOR _copy_no IN 1.._item.quantity LOOP
      _item_no := _item_no + 1;
      _claim_code := public.generate_claim_code();
      -- md5 over random value, time and order id is sufficient for the public
      -- registration token and does not require the pgcrypto extension.
      _token := md5(random()::text || clock_timestamp()::text || _order_id::text);

      INSERT INTO public.inventory_units (
        stock_batch_id,
        card_design_id,
        internal_inventory_code,
        business_status,
        fulfillment_status,
        traveler_user_id,
        order_id,
        order_item_id,
        public_claim_code,
        public_claim_token_hash,
        qr_generated_at
      )
      VALUES (
        _batch_id,
        _item.card_design_id,
        'POD-' || upper(substr(replace(_order_id::text, '-', ''), 1, 8)) || '-' || lpad(_item_no::text, 3, '0'),
        'purchased',
        'qr_generated',
        _order.user_id,
        _order_id::text,
        _item.id::text,
        _claim_code,
        -- This column also accepts legacy SHA-256 hashes. POD tokens are stored
        -- as an unguessable 32-character value because this database does not
        -- expose a server-side SHA-256 helper.
        _token,
        now()
      )
      RETURNING id INTO _unit_id;

      INSERT INTO public.qr_print_job_items (
        print_job_id, inventory_unit_id, public_claim_code, qr_url
      )
      VALUES (
        _job_id,
        _unit_id,
        _claim_code,
        '/r/' || _token
      );
    END LOOP;
  END LOOP;

  IF _item_no = 0 THEN
    RAISE EXCEPTION 'order_has_no_items';
  END IF;

  UPDATE public.qr_print_jobs
  SET status = 'ready', total_items = _item_no, generated_items = _item_no
  WHERE id = _job_id;

  RETURN _job_id;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."prepare_pod_order_after_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.payment_status = 'paid'
     AND (TG_OP = 'INSERT' OR OLD.payment_status IS DISTINCT FROM 'paid') THEN
    PERFORM public.prepare_pod_order(NEW.id);
  END IF;
  RETURN NEW;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."recalculate_user_gamification"("_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _unit_count int;
  _unique_countries int;
  _reg_count int;
  _total int;
  _rank text;
BEGIN
  SELECT
    COUNT(*)::int,
    COUNT(DISTINCT cd.country_id)::int
  INTO _unit_count, _unique_countries
  FROM public.inventory_units iu
  JOIN public.card_designs cd ON cd.id = iu.card_design_id
  WHERE iu.traveler_user_id = _user_id;

  SELECT COUNT(*)::int INTO _reg_count
  FROM public.recipient_registrations rr
  JOIN public.inventory_units iu ON iu.id = rr.inventory_unit_id
  WHERE iu.traveler_user_id = _user_id;

  _total := (_unit_count * 10) + (_unique_countries * 50) + (_reg_count * 100);

  _rank := CASE
    WHEN _total >= 7500 THEN 'Legenda PodrĂłĹĽĂłwki'
    WHEN _total >= 2500 THEN 'Misjonarz Kultury'
    WHEN _total >= 500 THEN 'Ambasador'
    ELSE 'Zwiadowca'
  END;

  UPDATE public.profiles
  SET total_points = _total,
      current_rank = _rank
  WHERE user_id = _user_id;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."register_recipient"("_unit_id" "uuid", "_recipient_name" "text", "_recipient_message" "text", "_recipient_email" "text", "_contact_opt_in" boolean, "_latitude" numeric, "_longitude" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _status text;
BEGIN
  SELECT business_status INTO _status
  FROM public.inventory_units
  WHERE id = _unit_id
  FOR UPDATE;

  IF _status IS NULL THEN
    RAISE EXCEPTION 'not_found';
  END IF;
  IF _status = 'registered' THEN
    RAISE EXCEPTION 'already_registered';
  END IF;
  IF _status <> 'purchased' THEN
    RAISE EXCEPTION 'not_activated';
  END IF;

  INSERT INTO public.recipient_registrations(
    inventory_unit_id, recipient_name, recipient_message, recipient_email,
    contact_opt_in, latitude, longitude
  ) VALUES (
    _unit_id, _recipient_name, _recipient_message, _recipient_email,
    _contact_opt_in, _latitude, _longitude
  );

  UPDATE public.inventory_units
  SET business_status = 'registered', registered_at = now()
  WHERE id = _unit_id;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."register_recipient"("_unit_id" "uuid", "_recipient_name" "text", "_recipient_message" "text", "_recipient_email" "text", "_contact_opt_in" boolean, "_latitude" numeric, "_longitude" numeric, "_registered_country_iso2" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _status text;
BEGIN
  SELECT business_status INTO _status
  FROM public.inventory_units
  WHERE id = _unit_id
  FOR UPDATE;

  IF _status IS NULL THEN
    RAISE EXCEPTION 'not_found';
  END IF;

  IF _status = 'registered' THEN
    RAISE EXCEPTION 'already_registered';
  END IF;

  IF _status <> 'purchased' THEN
    RAISE EXCEPTION 'not_activated';
  END IF;

  INSERT INTO public.recipient_registrations(
    inventory_unit_id, recipient_name, recipient_message, recipient_email,
    contact_opt_in, latitude, longitude, registered_country_iso2
  ) VALUES (
    _unit_id, _recipient_name, _recipient_message, _recipient_email,
    _contact_opt_in, _latitude, _longitude, _registered_country_iso2
  );

  UPDATE public.inventory_units
  SET business_status = 'registered', registered_at = now()
  WHERE id = _unit_id;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."reserve_inventory_for_order"("_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _order RECORD;
  _item RECORD;
  _reserved_count INTEGER;
  _available_count INTEGER;
  _unit_ids UUID[];
  _result JSONB := '{"reserved": []}'::jsonb;
  _errors JSONB := '[]'::jsonb;
BEGIN
  -- Admin-only check
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
  END IF;

  SELECT * INTO _order FROM public.orders WHERE id = _order_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'ZamĂłwienie nie istnieje');
  END IF;

  IF _order.payment_status != 'paid' THEN
    RETURN jsonb_build_object('success', false, 'error', 'ZamĂłwienie nie jest opĹ‚acone');
  END IF;

  SELECT COUNT(*) INTO _reserved_count
  FROM public.inventory_units
  WHERE order_id = _order_id::text;

  IF _reserved_count > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'ZamĂłwienie ma juĹĽ zarezerwowane sztuki (' || _reserved_count || ')');
  END IF;

  FOR _item IN
    SELECT oi.id AS item_id, oi.card_design_id, oi.quantity
    FROM public.order_items oi
    WHERE oi.order_id = _order_id
  LOOP
    SELECT COUNT(*) INTO _available_count
    FROM public.inventory_units
    WHERE card_design_id = _item.card_design_id
      AND fulfillment_status = 'in_stock'
      AND order_id IS NULL;

    IF _available_count < _item.quantity THEN
      _errors := _errors || jsonb_build_array(jsonb_build_object(
        'card_design_id', _item.card_design_id,
        'requested', _item.quantity,
        'available', _available_count
      ));
    END IF;
  END LOOP;

  IF jsonb_array_length(_errors) > 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Brak wystarczajÄ…cej iloĹ›ci sztuk w magazynie',
      'shortages', _errors
    );
  END IF;

  FOR _item IN
    SELECT oi.id AS item_id, oi.card_design_id, oi.quantity
    FROM public.order_items oi
    WHERE oi.order_id = _order_id
  LOOP
    SELECT ARRAY_AGG(id) INTO _unit_ids
    FROM (
      SELECT id
      FROM public.inventory_units
      WHERE card_design_id = _item.card_design_id
        AND fulfillment_status = 'in_stock'
        AND order_id IS NULL
      ORDER BY created_at ASC
      LIMIT _item.quantity
      FOR UPDATE SKIP LOCKED
    ) sub;

    UPDATE public.inventory_units
    SET fulfillment_status = 'reserved',
        business_status = 'purchased',
        traveler_user_id = _order.user_id,
        order_id = _order_id::text,
        order_item_id = _item.item_id::text
    WHERE id = ANY(_unit_ids);

    _result := jsonb_set(_result, '{reserved}',
      (_result->'reserved') || jsonb_build_array(jsonb_build_object(
        'order_item_id', _item.item_id,
        'card_design_id', _item.card_design_id,
        'count', array_length(_unit_ids, 1)
      ))
    );
  END LOOP;

  RETURN jsonb_build_object('success', true, 'details', _result);
END;
$$;




CREATE OR REPLACE FUNCTION "public"."update_country_count"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.platform_stats
  SET total_countries = (
    SELECT COUNT(DISTINCT c.id)
    FROM public.postcards p
    JOIN public.designs d ON p.design_id = d.id
    JOIN public.countries c ON d.country_id = c.id
    WHERE p.status IN ('purchased', 'registered')
  );
END;
$$;




CREATE OR REPLACE FUNCTION "public"."update_member_count"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    UPDATE public.platform_stats
    SET total_members = (SELECT COUNT(*) FROM public.profiles);
    RETURN NEW;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."update_platform_stats_on_postcard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Update total_purchased on insert
    IF TG_OP = 'INSERT' THEN
        UPDATE public.platform_stats
        SET total_purchased = total_purchased + 1;
    END IF;

    -- Update total_given when status changes to delivered
    IF TG_OP = 'UPDATE' AND OLD.status != 'delivered' AND NEW.status = 'delivered' THEN
        UPDATE public.platform_stats
        SET total_given = total_given + 1;

        -- Update country count if new country
        IF NEW.given_to_country IS NOT NULL THEN
            UPDATE public.platform_stats
            SET total_countries = (
                SELECT COUNT(DISTINCT given_to_country)
                FROM public.postcards
                WHERE status = 'delivered' AND given_to_country IS NOT NULL
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."update_platform_stats_on_postcard_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- On purchase
  IF TG_OP = 'UPDATE' AND OLD.status = 'available' AND NEW.status = 'purchased' THEN
    UPDATE public.platform_stats
    SET total_purchased = total_purchased + 1;
  END IF;

  -- On registration
  IF TG_OP = 'UPDATE' AND OLD.status = 'purchased' AND NEW.status = 'registered' THEN
    UPDATE public.platform_stats
    SET total_registered = total_registered + 1;
  END IF;

  RETURN NEW;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."update_profile_stats_on_postcard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Update giver stats when postcard is delivered
    IF TG_OP = 'UPDATE' AND OLD.status != 'delivered' AND NEW.status = 'delivered' THEN
        UPDATE public.profiles
        SET postcards_given = postcards_given + 1
        WHERE user_id = NEW.owner_id;

        -- Update receiver stats if receiver exists
        IF NEW.receiver_id IS NOT NULL THEN
            UPDATE public.profiles
            SET postcards_received = postcards_received + 1
            WHERE user_id = NEW.receiver_id;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."update_profile_stats_on_postcard_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.status = 'available' AND NEW.status = 'purchased' AND NEW.buyer_id IS NOT NULL THEN
    UPDATE public.profiles
    SET postcards_purchased = postcards_purchased + 1
    WHERE user_id = NEW.buyer_id;
  END IF;

  RETURN NEW;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."update_updated_at_column"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."validate_postcard_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status NOT IN ('available', 'purchased', 'registered') THEN
    RAISE EXCEPTION 'Invalid postcard status: %', NEW.status;
  END IF;
  RETURN NEW;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."validate_profile_input"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF length(NEW.display_name) > 100 THEN
    RAISE EXCEPTION 'display_name too long (max 100)';
  END IF;
  IF length(NEW.first_name) > 50 THEN
    RAISE EXCEPTION 'first_name too long (max 50)';
  END IF;
  IF length(NEW.last_name) > 50 THEN
    RAISE EXCEPTION 'last_name too long (max 50)';
  END IF;
  IF length(NEW.bio) > 1000 THEN
    RAISE EXCEPTION 'bio too long (max 1000)';
  END IF;
  IF length(NEW.city) > 100 THEN
    RAISE EXCEPTION 'city too long (max 100)';
  END IF;
  IF length(NEW.country) > 100 THEN
    RAISE EXCEPTION 'country too long (max 100)';
  END IF;
  IF length(NEW.avatar_url) > 500 THEN
    RAISE EXCEPTION 'avatar_url too long (max 500)';
  END IF;
  RETURN NEW;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."validate_registration_input"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF length(NEW.recipient_name) > 100 THEN
    RAISE EXCEPTION 'recipient_name too long (max 100)';
  END IF;
  IF length(NEW.recipient_message) > 500 THEN
    RAISE EXCEPTION 'recipient_message too long (max 500)';
  END IF;
  IF length(NEW.recipient_email) > 255 THEN
    RAISE EXCEPTION 'recipient_email too long (max 255)';
  END IF;
  RETURN NEW;
END;
$$;




